 all.sort((a,b)=>a.d-b.d);for(const car of all){drawCar(car.x,car.y-19*car.scale,car.scale,COLORS[car.i],false,(racers[car.i].x-steer)*.08)}
 // player car
 if(invincible<=0||Math.floor(performance.now()/90)%2===0)drawCar(baseX,h*.83,1.08,COLORS[0],true,-steer*.11);
 // boost streaks
 if(boosting&&raceStarted&&!paused){ctx.save();ctx.globalAlpha=.35+Math.random()*.15;ctx.strokeStyle='#ffe18a';ctx.lineWidth=2;for(let i=0;i<8;i++){const x=Math.random()*w;ctx.beginPath();ctx.moveTo(x,h*.55+Math.random()*h*.4);ctx.lineTo(x+(x-w*.5)*.12,h);ctx.stroke()}ctx.restore()}
 drawMap();}
function drawMap(){const mw=mapCanvas.clientWidth,mh=mapCanvas.clientHeight;mctx.clearRect(0,0,mw,mh);mctx.lineCap='round';mctx.strokeStyle='#788087';mctx.lineWidth=5;mctx.beginPath();mctx.ellipse(mw*.5,mh*.5,mw*.37,mh*.31,0,0,Math.PI*2);mctx.stroke();mctx.strokeStyle='#2c3137';mctx.lineWidth=2;mctx.beginPath();mctx.ellipse(mw*.5,mh*.5,mw*.37,mh*.31,0,0,Math.PI*2);mctx.stroke();for(let i=0;i<racers.length;i++){const a=(racers[i].dist/LAP)*Math.PI*2-Math.PI/2,x=mw*.5+Math.cos(a)*mw*.37,y=mh*.5+Math.sin(a)*mh*.31;mctx.fillStyle=COLORS[i];mctx.beginPath();mctx.arc(x,y,i===0?4:3,0,Math.PI*2);mctx.fill();mctx.strokeStyle='#15171a';mctx.lineWidth=1;mctx.stroke()}}

