function setPips(){for(let i=0;i<4;i++){const el=$(`#pips${i}`);if(!el.childElementCount)for(let j=0;j<10;j++)el.appendChild(document.createElement('i'));const progress=clamp(racers[i].dist/TOTAL,0,1);[...el.children].forEach((pip,j)=>pip.classList.toggle('on',progress>=(j+1)/10-.01));const lap=Math.min(3,Math.floor(racers[i].dist/LAP)+1);$(`#lap${i||'0'}`).textContent=`LAP ${lap}/3`;}}
function updateHud(){setPips();const order=[...racers].sort((a,b)=>b.dist-a.dist);const place=order.indexOf(racers[0])+1;$('#playerPlace').textContent=`P${place}`;for(let i=1;i<4;i++)$(`#place${i}`).textContent=`P${order.indexOf(racers[i])+1}`;$('#speed').textContent=String(Math.round(racers[0].speed*1.18)).padStart(3,'0');$('#nitroBar').style.width=`${nitro}%`;$('#nitroText').textContent=nitro>98?'100% READY':`${Math.round(nitro)}%`;$('#turbo').disabled=nitro<7;$('#turboHint').textContent=nitro<7?'RECHARGING':boosting?'BOOSTING':'HOLD TO BOOST';$('#lives').setAttribute('aria-label',`${lives} lives`);[...$('#lives').children].forEach((e,i)=>e.classList.toggle('off',i>=lives));$('#clock').textContent=`${String(Math.floor(raceTime/60)).padStart(2,'0')}:${(raceTime%60).toFixed(1).padStart(4,'0')}`;}
function showToast(text){const t=$('#toast');t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),1100)}
function startRace(){if(finished){resetRace()}$('#overlay').classList.add('hidden');paused=false;raceStarted=false;$('#raceState').textContent='GET SET';let n=3;$('#countdown').textContent=n;const count=setInterval(()=>{if(paused){clearInterval(count);return}n--;if(n>0){$('#countdown').textContent=n}else if(n===0){$('#countdown').textContent='GO!';$('#raceState').textContent='RACING';raceStarted=true}else{clearInterval(count);$('#countdown').textContent='';}},800)}
function resetRace(){racers[0].dist=0;racers[0].speed=0;racers[1].dist=15;racers[2].dist=5;racers[3].dist=-7;raceTime=0;nitro=100;lives=3;steer=0;finished=false;invincible=0;crashCooldown=0;$('#playerLap').textContent='LAP 1/3';$('#raceState').textContent='GRID READY';}
function finishRace(){finished=true;raceStarted=false;boosting=false;$('#turbo').classList.remove('active');const place=1+[...racers.slice(1)].filter(r=>r.dist>racers[0].dist).length;$('#raceState').textContent='FINISH';$('#dialogEyebrow').textContent=place===1?'🏆 CHECKERED FLAG':'RACE COMPLETE';$('#dialogTitle').innerHTML=place===1?'You took<br>the crown!':`P${place} —<br>nice drive!`;$('#dialogText').textContent=`Three laps in ${$('#clock').textContent}. ${place===1?'The Snake Circuit is yours.':'Give it another run and chase the podium.'}`;$('#startBtn').textContent='Race again';$('#overlay').classList.remove('hidden')}
function crash(message){if(crashCooldown>0||invincible>0)return;crashCooldown=1.5;invincible=1.4;lives--;racers[0].speed*=.48;shake=.45;$('#flash').classList.add('on');setTimeout(()=>$('#flash').classList.remove('on'),110);showToast(message);if(lives<=0){raceStarted=false;boosting=false;$('#raceState').textContent='WRECKED';$('#dialogEyebrow').textContent='RACE OVER';$('#dialogTitle').innerHTML='Out of<br>lives';$('#dialogText').textContent='The pack got the better of you this time. Reset and take another shot.';$('#startBtn').textContent='Try again';$('#overlay').classList.remove('hidden')}}
function update(dt){if(!raceStarted||paused||finished)return;raceTime+=dt;invincible=Math.max(0,invincible-dt);crashCooldown=Math.max(0,crashCooldown-dt);const left=keys.ArrowLeft||keys.KeyA,right=keys.ArrowRight||keys.KeyD,up=keys.ArrowUp||keys.KeyW,down=keys.ArrowDown||keys.KeyS;let wanted=(right?1:0)-(left?1:0);if(Math.abs(steer)<.06&&Math.abs(wanted)<.1)wanted=steer;steer=clamp(steer+(wanted+ (steerPointerX||0)*1.25-steer)*Math.min(1,dt*5),-1.25,1.25);const throttle=up?1:down?-.8:.62;const target=throttle<0?65:throttle>0?MAX_SPEED:210;let velocity=lerp(racers[0].speed,target,dt*(throttle<0?1.8:throttle>0?1.0:.5));boosting=(boostHeld||keys.Space)&&nitro>1&&throttle>=0;if(boosting){velocity+=72;nitro=Math.max(0,nitro-30*dt)}else nitro=Math.min(100,nitro+(raceStarted?6:0)*dt);if(Math.abs(steer)>1){velocity*=.9;if(crashCooldown<=0)crash('KERB STRIKE — WATCH THE EDGE');}racers[0].speed=velocity;const gain=velocity*dt*(1+Math.max(0,steer)*.008);racers[0].dist+=gain;roadOffset+=gain;
 for(let i=1;i<4;i++){const r=racers[i];const pace=[0,197,189,181][i]+Math.sin((raceTime+i*2)*.5)*7;r.speed=pace;r.dist+=pace*dt;r.x=clamp(r.x+Math.sin(raceTime*.65+i*2)*dt*.04,-.48,.48)}
 // Steering follows road curvature; edges punish greedy shortcuts.
 const roadX=pseudoCurve(racers[0].dist);const carOffset=steer+roadX*.22;if(Math.abs(carOffset)>1.05){racers[0].speed*=.96;if(crashCooldown<=0)crash('OFF TRACK — BACK ON THE TARMAC')}
 for(let i=1;i<4;i++){const d=Math.abs(racers[i].dist-racers[0].dist);const near=Math.min(d,Math.abs(TOTAL-d));if(near<18&&Math.abs(racers[i].x-steer)<.27)crash('CONTACT! HOLD YOUR LINE')}
 if(racers[0].dist>=TOTAL){racers[0].dist=TOTAL;finishRace()}if(shake>0)shake=Math.max(0,shake-dt);updateHud();}
let steerPointerX=0,boostHeld=false;
function frame(now){const dt=Math.min(.04,(now-last)/1000||0);last=now;update(dt);if(shake>0){ctx.save();ctx.translate((Math.random()-.5)*shake*16,(Math.random()-.5)*shake*10);render();ctx.restore()}else render();requestAnimationFrame(frame)}requestAnimationFrame(frame);
function togglePause(){if(finished)return;if(!raceStarted&&!paused)return;paused=!paused;boosting=false;$('#turbo').classList.remove('active');if(paused){$('#raceState').textContent='PAUSED';$('#dialogEyebrow').textContent='TAKE A BREATHER';$('#dialogTitle').textContent='Race paused';$('#dialogText').textContent='Your rivals are frozen. Jump back in when you are ready.';$('#startBtn').textContent='Resume race';$('#overlay').classList.remove('hidden')}else{$('#overlay').classList.add('hidden');$('#raceState').textContent='RACING';last=performance.now()}}
$('#startBtn').addEventListener('click',()=>{if(paused){paused=false;$('#overlay').classList.add('hidden');$('#raceState').textContent='RACING';last=performance.now()}else startRace()});$('#pauseBtn').addEventListener('click',togglePause);
window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();keys[e.code]=true;if(e.code==='Escape'||e.code==='KeyP')togglePause()});window.addEventListener('keyup',e=>{keys[e.code]=false});window.addEventListener('blur',()=>{keys={};boostHeld=false;if(raceStarted&&!paused)togglePause()});
const stick=$('#stick'),knob=$('#knob');function moveStick(e){const r=stick.getBoundingClientRect(),dx=(e.clientX-(r.left+r.width/2))/(r.width*.34);steerPointerX=clamp(dx,-1,1);knob.style.left=`${50+steerPointerX*30}%`}function releaseStick(e){if(stickPointer!==e.pointerId)return;stickPointer=null;steerPointerX=0;knob.style.left='50%'}stick.addEventListener('pointerdown',e=>{e.preventDefault();stickPointer=e.pointerId;stick.setPointerCapture(e.pointerId);moveStick(e)});stick.addEventListener('pointermove',e=>{if(stickPointer===e.pointerId)moveStick(e)});stick.addEventListener('pointerup',releaseStick);stick.addEventListener('pointercancel',releaseStick);
const turbo=$('#turbo');function holdBoost(e){e.preventDefault();boostHeld=true;turbo.classList.add('active')}function releaseBoost(){boostHeld=false;turbo.classList.remove('active')}turbo.addEventListener('pointerdown',holdBoost);turbo.addEventListener('pointerup',releaseBoost);turbo.addEventListener('pointercancel',releaseBoost);turbo.addEventListener('pointerleave',e=>{if(e.buttons===0)releaseBoost()});
updateHud();
})();
</script>
</body>
</html>

